"""Defensive offline auditor for the synthetic QUIC v1 trace model."""

import json
import re
import sys
from collections import deque


MAX_N = 4611686018427387903
MAX_TIME = 1000000000000
MAX_REQUEST = 16 * 1024 * 1024
MAX_DECODED_DATA = 2 * 1024 * 1024
LEVELS = ("I", "H", "Z", "A")
CRYPTO_LEVELS = ("I", "H", "A")
ID_RE = re.compile(r"[A-Za-z0-9_-]{1,32}\Z")
HEX_RE = re.compile(r"[0-9a-f]*\Z")


class InvalidInput(Exception):
    pass


def _reject_constant(_value):
    raise InvalidInput()


def _reject_float(_value):
    # The grammar has JSON integers, never floating-point values.
    raise InvalidInput()


def _object_without_duplicates(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise InvalidInput()
        obj[key] = value
    return obj


def _exact_object(value, keys):
    if type(value) is not dict or set(value) != set(keys):
        raise InvalidInput()


def _array(value, minimum=None, maximum=None):
    if type(value) is not list:
        raise InvalidInput()
    if minimum is not None and len(value) < minimum:
        raise InvalidInput()
    if maximum is not None and len(value) > maximum:
        raise InvalidInput()


def _integer(value, low=0, high=MAX_N):
    if type(value) is not int or value < low or value > high:
        raise InvalidInput()


def _boolean(value):
    if type(value) is not bool:
        raise InvalidInput()


def _ranges(value):
    _array(value, maximum=32)
    result = []
    for pair in value:
        _array(pair, minimum=2, maximum=2)
        _integer(pair[0])
        _integer(pair[1])
        result.append((pair[0], pair[1]))
    return result


def _config_ranges(value):
    ranges = _ranges(value)
    previous_high = None
    for low, high in ranges:
        if low > high:
            raise InvalidInput()
        if previous_high is not None and low <= previous_high + 1:
            raise InvalidInput()
        previous_high = high
    return ranges


def _validate_config(config):
    keys = (
        "early", "overlap", "buffer_packets", "idle_ms",
        "max_streams_bidi", "max_streams_uni", "max_stream_data",
        "max_data", "crypto_limit", "sent",
    )
    _exact_object(config, keys)
    _boolean(config["early"])
    if config["overlap"] not in ("reject", "first") or type(config["overlap"]) is not str:
        raise InvalidInput()
    _integer(config["buffer_packets"], 0, 1024)
    _integer(config["idle_ms"], 0, 1000000000)
    _integer(config["max_streams_bidi"], 0, 1024)
    _integer(config["max_streams_uni"], 0, 1024)
    _integer(config["max_stream_data"], 0, 65536)
    _integer(config["max_data"])
    _integer(config["crypto_limit"], 0, 65536)
    _exact_object(config["sent"], ("I", "H", "A"))
    # Replace the public JSON shape with canonical integer tuples internally.
    config["sent"] = {
        level: _config_ranges(config["sent"][level]) for level in ("I", "H", "A")
    }


def _validate_hex(value):
    if type(value) is not str or len(value) > 4096 or len(value) & 1:
        raise InvalidInput()
    if HEX_RE.fullmatch(value) is None:
        raise InvalidInput()
    return len(value) // 2


def _validate_frame(frame):
    if type(frame) is not dict or type(frame.get("type")) is not str:
        raise InvalidInput()
    kind = frame["type"]

    if kind in ("PADDING", "PING", "HANDSHAKE_DONE", "UNKNOWN"):
        _exact_object(frame, ("type",))
        return 0
    if kind == "ACK":
        _exact_object(frame, ("type", "ranges"))
        frame["ranges"] = _ranges(frame["ranges"])
        return 0
    if kind == "CRYPTO":
        _exact_object(frame, ("type", "offset", "data_hex"))
        _integer(frame["offset"])
        size = _validate_hex(frame["data_hex"])
        frame["data"] = bytes.fromhex(frame["data_hex"])
        return size
    if kind == "STREAM":
        _exact_object(frame, ("type", "id", "offset", "data_hex", "fin"))
        _integer(frame["id"])
        _integer(frame["offset"])
        _boolean(frame["fin"])
        size = _validate_hex(frame["data_hex"])
        frame["data"] = bytes.fromhex(frame["data_hex"])
        return size
    if kind == "RESET_STREAM":
        _exact_object(frame, ("type", "id", "final_size"))
        _integer(frame["id"])
        _integer(frame["final_size"])
        return 0
    if kind == "STOP_SENDING":
        _exact_object(frame, ("type", "id"))
        _integer(frame["id"])
        return 0
    if kind == "CLOSE":
        _exact_object(frame, ("type", "app", "code"))
        _boolean(frame["app"])
        _integer(frame["code"])
        return 0
    raise InvalidInput()


def _validate_packet(packet):
    _exact_object(packet, ("level", "pn", "auth", "frames"))
    if packet["level"] not in LEVELS or type(packet["level"]) is not str:
        raise InvalidInput()
    _integer(packet["pn"])
    _boolean(packet["auth"])
    _array(packet["frames"], maximum=64)
    decoded = 0
    for frame in packet["frames"]:
        decoded += _validate_frame(frame)
        if decoded > MAX_DECODED_DATA:
            # The global check below is still needed; this merely avoids work
            # on an already impossible packet.
            raise InvalidInput()
    return decoded


def _validate_event(event, previous_time):
    if type(event) is not dict:
        raise InvalidInput()
    if "t" not in event or "op" not in event:
        raise InvalidInput()
    _integer(event["t"], 0, MAX_TIME)
    if previous_time is not None and event["t"] < previous_time:
        raise InvalidInput()
    if type(event["op"]) is not str:
        raise InvalidInput()
    op = event["op"]
    if op == "tick":
        _exact_object(event, ("t", "op"))
        return event["t"], 0, 0, 0
    if op == "key":
        _exact_object(event, ("t", "op", "level", "action"))
        if event["level"] not in LEVELS or type(event["level"]) is not str:
            raise InvalidInput()
        if event["action"] not in ("install", "discard") or type(event["action"]) is not str:
            raise InvalidInput()
        return event["t"], 0, 0, 0
    if op == "datagram":
        _exact_object(event, ("t", "op", "bytes", "packets"))
        _integer(event["bytes"], 0, 65535)
        _array(event["packets"], minimum=1, maximum=16)
        packet_count = len(event["packets"])
        frame_count = 0
        decoded = 0
        for packet in event["packets"]:
            decoded += _validate_packet(packet)
            frame_count += len(packet["frames"])
            if decoded > MAX_DECODED_DATA:
                raise InvalidInput()
        return event["t"], packet_count, frame_count, decoded
    raise InvalidInput()


def validate_request(root):
    _exact_object(root, ("version", "traces"))
    if type(root["version"]) is not int or root["version"] != 1:
        raise InvalidInput()
    _array(root["traces"], maximum=32)

    event_total = 0
    packet_total = 0
    frame_total = 0
    decoded_total = 0
    trace_ids = set()

    for trace in root["traces"]:
        _exact_object(trace, ("id", "config", "events"))
        if type(trace["id"]) is not str or ID_RE.fullmatch(trace["id"]) is None:
            raise InvalidInput()
        if trace["id"] in trace_ids:
            raise InvalidInput()
        trace_ids.add(trace["id"])
        _validate_config(trace["config"])
        _array(trace["events"])
        previous_time = None
        for event in trace["events"]:
            event_total += 1
            if event_total > 20000:
                raise InvalidInput()
            previous_time, packets, frames, decoded = _validate_event(event, previous_time)
            packet_total += packets
            frame_total += frames
            decoded_total += decoded
            if packet_total > 20000 or frame_total > 60000 or decoded_total > MAX_DECODED_DATA:
                raise InvalidInput()
    return root


class PacketRecord:
    __slots__ = ("event", "packet", "level", "pn", "auth", "frames", "arrival", "result")

    def __init__(self, event, packet_index, packet, arrival, result):
        self.event = event
        self.packet = packet_index
        self.level = packet["level"]
        self.pn = packet["pn"]
        self.auth = packet["auth"]
        self.frames = packet["frames"]
        self.arrival = arrival
        self.result = result


class StreamState:
    __slots__ = ("highest", "final_size", "reset", "stopped", "delivered", "data")

    def __init__(self):
        self.highest = 0
        self.final_size = None
        self.reset = False
        self.stopped = False
        self.delivered = 0
        self.data = {}


class CryptoState:
    __slots__ = ("highest", "contiguous", "data")

    def __init__(self):
        self.highest = 0
        self.contiguous = 0
        self.data = {}


class Transaction:
    """Undo only scalar changes and newly inserted bytes for one packet."""

    __slots__ = ("receiver", "streams", "cryptos", "inserted", "received_total")

    def __init__(self, receiver):
        self.receiver = receiver
        self.streams = {}
        self.cryptos = {}
        self.inserted = []
        self.received_total = receiver.received_total

    def stream(self, sid):
        if sid not in self.streams:
            old = self.receiver.streams.get(sid)
            if old is None:
                self.streams[sid] = None
                old = StreamState()
                self.receiver.streams[sid] = old
            else:
                self.streams[sid] = (
                    old.highest, old.final_size, old.reset, old.stopped, old.delivered
                )
        return self.receiver.streams[sid]

    def crypto(self, level):
        if level not in self.cryptos:
            state = self.receiver.crypto[level]
            self.cryptos[level] = (state.highest, state.contiguous)
        return self.receiver.crypto[level]

    def insert(self, data, offset, value):
        data[offset] = value
        self.inserted.append((data, offset))

    def rollback(self):
        for data, offset in self.inserted:
            # Every logged position was absent before this packet inserted it.
            data.pop(offset, None)
        for sid, snapshot in self.streams.items():
            if snapshot is None:
                self.receiver.streams.pop(sid, None)
            else:
                state = self.receiver.streams[sid]
                (state.highest, state.final_size, state.reset,
                 state.stopped, state.delivered) = snapshot
        for level, snapshot in self.cryptos.items():
            state = self.receiver.crypto[level]
            state.highest, state.contiguous = snapshot
        self.receiver.received_total = self.received_total


class PacketFailure(Exception):
    def __init__(self, code, frame):
        self.code = code
        self.frame = frame


class Receiver:
    def __init__(self, trace):
        self.trace_id = trace["id"]
        self.config = trace["config"]
        self.keys = {
            "I": "live",
            "H": "absent",
            "Z": "live" if self.config["early"] else "absent",
            "A": "absent",
        }
        self.queues = {level: deque() for level in LEVELS}
        self.queue_count = 0
        self.pn_sets = {"I": set(), "H": set(), "A": set()}
        self.streams = {}
        self.crypto = {level: CryptoState() for level in CRYPTO_LEVELS}
        self.received_total = 0
        self.results = []

        self.state = "open"
        self.code = None
        self.closed_at = None
        self.source = None
        self.peer_code = None
        self.last_activity = 0

    def _set_result(self, record, status, reason, at_ms, frame=None):
        record.result.update({
            "status": status,
            "reason": reason,
            "at_ms": at_ms,
            "frame": frame,
        })

    def _drop_pending_level(self, level, reason, at_ms):
        queue = self.queues[level]
        while queue:
            record = queue.popleft()
            self.queue_count -= 1
            self._set_result(record, "dropped", reason, at_ms)

    def _drop_all_pending(self, at_ms):
        for level in LEVELS:
            self._drop_pending_level(level, "CONNECTION_CLOSED", at_ms)

    def _terminate(self, state, code, at_ms, source, peer_code=None):
        self.state = state
        self.code = code
        self.closed_at = at_ms
        self.source = source
        self.peer_code = peer_code
        self._drop_all_pending(at_ms)

    def _idle_check(self, event_index, time):
        idle = self.config["idle_ms"]
        if self.state == "open" and idle and time >= self.last_activity + idle:
            deadline = self.last_activity + idle
            self._terminate(
                "idle", "IDLE_TIMEOUT", deadline,
                {"event": event_index, "packet": None, "frame": None},
            )

    def _preflight(self, frames):
        if not frames:
            raise PacketFailure("FRAME_ENCODING_ERROR", None)
        for index, frame in enumerate(frames):
            kind = frame["type"]
            if kind == "UNKNOWN":
                raise PacketFailure("FRAME_ENCODING_ERROR", index)
            allowed = True
            if kind in ("PADDING", "PING"):
                allowed = True
            elif kind in ("ACK", "CRYPTO"):
                allowed = self._processing_level in ("I", "H", "A")
            elif kind in ("STREAM", "RESET_STREAM", "STOP_SENDING"):
                allowed = self._processing_level in ("Z", "A")
            elif kind == "CLOSE":
                allowed = (not frame["app"]) or self._processing_level in ("Z", "A")
            elif kind == "HANDSHAKE_DONE":
                allowed = False
            if not allowed:
                raise PacketFailure("PROTOCOL_VIOLATION", index)

    def _check_stream_name(self, sid, stop=False):
        direction = sid & 3
        if stop:
            if direction != 0:
                raise PacketFailure("STREAM_STATE_ERROR", self._frame_index)
            limit = self.config["max_streams_bidi"]
        else:
            if direction not in (0, 2):
                raise PacketFailure("STREAM_STATE_ERROR", self._frame_index)
            limit = (self.config["max_streams_bidi"] if direction == 0
                     else self.config["max_streams_uni"])
        if sid // 4 + 1 > limit:
            raise PacketFailure("STREAM_LIMIT_ERROR", self._frame_index)

    def _store_bytes(self, data, incoming, offset, transaction):
        reject = self.config["overlap"] == "reject"
        for index, value in enumerate(incoming):
            position = offset + index
            old = data.get(position)
            if old is not None:
                if old != value and reject:
                    raise PacketFailure("PROTOCOL_VIOLATION", self._frame_index)
                # Identical overlap, and all overlap under `first`, retain the
                # already stored byte.
            else:
                transaction.insert(data, position, value)

    @staticmethod
    def _advance_prefix(data, start):
        while start in data:
            start += 1
        return start

    def _stream_frame(self, frame, transaction):
        sid = frame["id"]
        self._check_stream_name(sid)
        stream = transaction.stream(sid)
        incoming = frame["data"]
        end = frame["offset"] + len(incoming)
        if end > MAX_N:
            raise PacketFailure("FRAME_ENCODING_ERROR", self._frame_index)
        final_size = stream.final_size
        fin = frame["fin"]
        if final_size is not None and (end > final_size or (fin and end != final_size)):
            raise PacketFailure("FINAL_SIZE_ERROR", self._frame_index)
        if fin and end < stream.highest:
            raise PacketFailure("FINAL_SIZE_ERROR", self._frame_index)
        if end > self.config["max_stream_data"]:
            raise PacketFailure("FLOW_CONTROL_ERROR", self._frame_index)
        new_highest = max(stream.highest, end)
        new_total = self.received_total + new_highest - stream.highest
        if new_total > self.config["max_data"]:
            raise PacketFailure("FLOW_CONTROL_ERROR", self._frame_index)
        if not stream.reset:
            self._store_bytes(stream.data, incoming, frame["offset"], transaction)
        self.received_total = new_total
        stream.highest = new_highest
        if fin:
            stream.final_size = end
        if not stream.reset:
            stream.delivered = self._advance_prefix(stream.data, stream.delivered)

    def _reset_frame(self, frame, transaction):
        sid = frame["id"]
        self._check_stream_name(sid)
        stream = transaction.stream(sid)
        size = frame["final_size"]
        if stream.final_size is not None and size != stream.final_size:
            raise PacketFailure("FINAL_SIZE_ERROR", self._frame_index)
        if size < stream.highest:
            raise PacketFailure("FINAL_SIZE_ERROR", self._frame_index)
        if size > self.config["max_stream_data"]:
            raise PacketFailure("FLOW_CONTROL_ERROR", self._frame_index)
        new_highest = max(stream.highest, size)
        new_total = self.received_total + new_highest - stream.highest
        if new_total > self.config["max_data"]:
            raise PacketFailure("FLOW_CONTROL_ERROR", self._frame_index)
        self.received_total = new_total
        stream.highest = new_highest
        stream.final_size = size
        stream.reset = True

    def _stop_frame(self, frame, transaction):
        sid = frame["id"]
        self._check_stream_name(sid, stop=True)
        transaction.stream(sid).stopped = True

    def _crypto_frame(self, frame, transaction):
        state = transaction.crypto(self._processing_level)
        incoming = frame["data"]
        end = frame["offset"] + len(incoming)
        if end > MAX_N:
            raise PacketFailure("FRAME_ENCODING_ERROR", self._frame_index)
        if end > self.config["crypto_limit"]:
            raise PacketFailure("CRYPTO_BUFFER_EXCEEDED", self._frame_index)
        self._store_bytes(state.data, incoming, frame["offset"], transaction)
        state.highest = max(state.highest, end)
        state.contiguous = self._advance_prefix(state.data, state.contiguous)

    def _ack_frame(self, frame):
        ranges = frame["ranges"]
        if not ranges:
            raise PacketFailure("FRAME_ENCODING_ERROR", self._frame_index)
        previous_high = None
        for low, high in ranges:
            if low > high:
                raise PacketFailure("FRAME_ENCODING_ERROR", self._frame_index)
            if previous_high is not None and low <= previous_high + 1:
                raise PacketFailure("FRAME_ENCODING_ERROR", self._frame_index)
            previous_high = high

        sent = self.config["sent"][self._processing_level]
        sent_index = 0
        sent_count = len(sent)
        for low, high in ranges:
            position = low
            while position <= high:
                while sent_index < sent_count and sent[sent_index][1] < position:
                    sent_index += 1
                if sent_index == sent_count or sent[sent_index][0] > position:
                    raise PacketFailure("PROTOCOL_VIOLATION", self._frame_index)
                position = min(high, sent[sent_index][1]) + 1

    def _semantics(self, frames):
        transaction = Transaction(self)
        for index, frame in enumerate(frames):
            self._frame_index = index
            kind = frame["type"]
            if kind in ("PADDING", "PING"):
                continue
            if kind == "STREAM":
                self._stream_frame(frame, transaction)
            elif kind == "RESET_STREAM":
                self._reset_frame(frame, transaction)
            elif kind == "STOP_SENDING":
                self._stop_frame(frame, transaction)
            elif kind == "CRYPTO":
                self._crypto_frame(frame, transaction)
            elif kind == "ACK":
                self._ack_frame(frame)
            elif kind == "CLOSE":
                return transaction, frame
            # HANDSHAKE_DONE and UNKNOWN cannot pass preflight.
        return transaction, None

    def _process_live(self, record, time):
        if not record.auth:
            self._set_result(record, "dropped", "AUTH", time)
            return
        number_space = record.level if record.level in ("I", "H") else "A"
        if record.pn in self.pn_sets[number_space]:
            self._set_result(record, "duplicate", "DUPLICATE", time)
            return

        self._processing_level = record.level
        try:
            self._preflight(record.frames)
            transaction, close = self._semantics(record.frames)
        except PacketFailure as failure:
            # _semantics only exposes its transaction on success, so semantic
            # rollback is performed in the wrapper below via _active_transaction.
            self._set_result(record, "error", failure.code, time, failure.frame)
            self._terminate(
                "closed", failure.code, time,
                {"event": record.event, "packet": record.packet, "frame": failure.frame},
            )
            return

        self.pn_sets[number_space].add(record.pn)
        self.last_activity = time
        self._set_result(record, "accepted", "OK", time)
        if close is not None:
            self._terminate(
                "closed",
                "PEER_APPLICATION_CLOSE" if close["app"] else "PEER_TRANSPORT_CLOSE",
                time,
                {"event": record.event, "packet": record.packet, "frame": self._frame_index},
                close["code"],
            )

    def _process_packet(self, record, time):
        """Process a packet whose keys are live, with atomic frame effects."""
        # This wrapper installs a transaction rollback hook without copying any
        # of the potentially large sparse reassembly maps.
        if not record.auth:
            self._set_result(record, "dropped", "AUTH", time)
            return
        number_space = record.level if record.level in ("I", "H") else "A"
        if record.pn in self.pn_sets[number_space]:
            self._set_result(record, "duplicate", "DUPLICATE", time)
            return

        self._processing_level = record.level
        try:
            self._preflight(record.frames)
        except PacketFailure as failure:
            self._packet_error(record, failure, time)
            return

        transaction = Transaction(self)
        try:
            close = None
            for index, frame in enumerate(record.frames):
                self._frame_index = index
                kind = frame["type"]
                if kind in ("PADDING", "PING"):
                    continue
                if kind == "STREAM":
                    self._stream_frame(frame, transaction)
                elif kind == "RESET_STREAM":
                    self._reset_frame(frame, transaction)
                elif kind == "STOP_SENDING":
                    self._stop_frame(frame, transaction)
                elif kind == "CRYPTO":
                    self._crypto_frame(frame, transaction)
                elif kind == "ACK":
                    self._ack_frame(frame)
                elif kind == "CLOSE":
                    close = frame
                    break
        except PacketFailure as failure:
            transaction.rollback()
            self._packet_error(record, failure, time)
            return

        self.pn_sets[number_space].add(record.pn)
        self.last_activity = time
        self._set_result(record, "accepted", "OK", time)
        if close is not None:
            self._terminate(
                "closed",
                "PEER_APPLICATION_CLOSE" if close["app"] else "PEER_TRANSPORT_CLOSE",
                time,
                {"event": record.event, "packet": record.packet, "frame": self._frame_index},
                close["code"],
            )

    def _packet_error(self, record, failure, time):
        self._set_result(record, "error", failure.code, time, failure.frame)
        self._terminate(
            "closed", failure.code, time,
            {"event": record.event, "packet": record.packet, "frame": failure.frame},
        )

    def _arrive(self, record, time, datagram_size):
        if self.state != "open":
            self._set_result(record, "dropped", "CONNECTION_CLOSED", time)
        elif record.level == "I" and datagram_size < 1200:
            self._set_result(record, "dropped", "INITIAL_TOO_SMALL", time)
        elif record.level == "Z" and not self.config["early"]:
            self._set_result(record, "dropped", "EARLY_REJECTED", time)
        elif self.keys[record.level] == "discarded":
            self._set_result(record, "dropped", "KEYS_DISCARDED", time)
        elif self.keys[record.level] == "absent":
            if self.queue_count >= self.config["buffer_packets"]:
                self._set_result(record, "dropped", "BUFFER_FULL", time)
            else:
                self.queues[record.level].append(record)
                self.queue_count += 1
        else:
            self._process_packet(record, time)

    def _datagram(self, event_index, event):
        time = event["t"]
        packets = event["packets"]
        records = []
        for packet_index, packet in enumerate(packets):
            result = {
                "event": event_index,
                "packet": packet_index,
                "status": None,
                "reason": None,
                "at_ms": None,
                "frame": None,
            }
            self.results.append(result)
            records.append(PacketRecord(
                event_index, packet_index, packet, time, result
            ))

        if self.state == "open" and any(
                record.level == "A" and index != len(records) - 1
                for index, record in enumerate(records)):
            for record in records:
                self._set_result(record, "dropped", "LAYOUT", time)
            return

        for record in records:
            self._arrive(record, time, event["bytes"])

    def _key(self, event):
        level = event["level"]
        action = event["action"]
        time = event["t"]
        if self.state != "open":
            return
        if action == "discard":
            if self.keys[level] != "discarded":
                self.keys[level] = "discarded"
            self._drop_pending_level(level, "KEYS_DISCARDED", time)
            return
        if self.keys[level] != "absent":
            return
        self.keys[level] = "live"
        queue = self.queues[level]
        while queue and self.state == "open":
            record = queue.popleft()
            self.queue_count -= 1
            self._process_packet(record, time)

    def run(self):
        for event_index, event in enumerate(self.trace_events):
            self._idle_check(event_index, event["t"])
            if event["op"] == "datagram":
                self._datagram(event_index, event)
            elif self.state == "open":
                if event["op"] == "key":
                    self._key(event)
                # A tick has no further effect.

        if self.state == "open":
            for level in LEVELS:
                for record in self.queues[level]:
                    self._set_result(record, "buffered", "NO_KEYS", record.arrival)

        return self.output()

    def output(self):
        streams = []
        for sid in sorted(self.streams):
            stream = self.streams[sid]
            delivered = bytes(stream.data[offset] for offset in range(stream.delivered))
            streams.append({
                "id": sid,
                "highest": stream.highest,
                "final_size": stream.final_size,
                "reset": stream.reset,
                "stopped": stream.stopped,
                "delivered_hex": delivered.hex(),
            })
        crypto = []
        for level in CRYPTO_LEVELS:
            state = self.crypto[level]
            contiguous = bytes(state.data[offset] for offset in range(state.contiguous))
            crypto.append({
                "level": level,
                "highest": state.highest,
                "contiguous_hex": contiguous.hex(),
            })
        return {
            "id": self.trace_id,
            "packets": self.results,
            "connection": {
                "state": self.state,
                "code": self.code,
                "at_ms": self.closed_at,
                "source": self.source,
                "peer_code": self.peer_code,
                "last_activity_ms": self.last_activity,
            },
            "keys": self.keys,
            "received_total": self.received_total,
            "streams": streams,
            "crypto": crypto,
        }


def replay(root):
    results = []
    for trace in root["traces"]:
        receiver = Receiver(trace)
        receiver.trace_events = trace["events"]
        results.append(receiver.run())
    return {"version": 1, "results": results}


def main():
    try:
        raw = sys.stdin.buffer.read(MAX_REQUEST + 1)
        if len(raw) > MAX_REQUEST:
            raise InvalidInput()
        text = raw.decode("utf-8", "strict")
        root = json.loads(
            text,
            object_pairs_hook=_object_without_duplicates,
            parse_constant=_reject_constant,
            parse_float=_reject_float,
        )
        validate_request(root)
        answer = replay(root)
    except (InvalidInput, UnicodeError, ValueError, TypeError, RecursionError, json.JSONDecodeError):
        answer = {"error": "INVALID_INPUT"}
    sys.stdout.write(json.dumps(answer, separators=(",", ":")) + "\n")


if __name__ == "__main__":
    main()
